/**
 * JSON Canonicalization Scheme (RFC 8785) for the Machine Payments Protocol.
 *
 * A Payment challenge binds its parameters with an HMAC, and one of those
 * parameters is the base64url of a JCS-serialized JSON object. Two peers that
 * canonicalize differently compute different HMAC inputs, and the only
 * symptom is a challenge the server refuses with no explanation of why. So
 * this module deliberately reproduces the Go reference implementation in
 * aperture's `mpp` package byte for byte, and the vector-driven tests in
 * `jcs.test.ts` pin that agreement against output generated by the Go code
 * itself.
 *
 * Two places where the reference implementation departs from RFC 8785, which
 * this module follows because interoperating with the reference matters more
 * than matching the RFC in isolation:
 *
 *  1. Object keys sort by Unicode code point, not by UTF-16 code unit. The
 *     two orders agree for every character below U+10000 and disagree above
 *     it, where the RFC would sort an astral character before U+E000..U+FFFF
 *     and this module sorts it after. Go's `sort.Strings` compares UTF-8
 *     bytes, which is code point order.
 *
 *  2. Strings escape "<", ">", "&", U+2028, and U+2029, because Go's
 *     `encoding/json` escapes them by default. The RFC leaves all five
 *     unescaped.
 *
 * Both divergences only bite on inputs the protocol's own payloads never
 * contain, which is why they have gone unnoticed; the tests pin them anyway
 * so a future change to either side is caught here rather than in a failing
 * HMAC on a live server.
 */

/** The JSON value domain this canonicalizer accepts. */
export type JsonValue =
  | null
  | boolean
  | number
  | string
  | JsonValue[]
  | { [key: string]: JsonValue | undefined };

/**
 * Serialize a value to its canonical JSON form.
 *
 * Object properties whose value is `undefined` are omitted, matching both
 * `JSON.stringify` and the `omitempty` behavior of the Go structs on the
 * other side of the wire. An `undefined` inside an array throws instead:
 * `JSON.stringify` would silently turn it into `null`, and a silent
 * substitution inside something that gets signed is the failure mode this
 * module exists to prevent.
 */
export function canonicalize(value: JsonValue): string {
  const out: string[] = [];
  writeValue(out, value);
  return out.join("");
}

/**
 * Parse raw JSON text and re-serialize it in canonical form.
 *
 * This is the counterpart of the reference implementation's
 * `CanonicalizeJSON`, and the operation a seller performs when it has a
 * request object as bytes rather than as a value.
 */
export function canonicalizeJson(raw: string): string {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new Error(`jcs: failed to parse JSON: ${describeError(err)}`);
  }
  return canonicalize(parsed as JsonValue);
}

function writeValue(out: string[], value: JsonValue | undefined): void {
  if (value === null) {
    out.push("null");
    return;
  }

  switch (typeof value) {
    case "boolean":
      out.push(value ? "true" : "false");
      return;

    case "number":
      out.push(formatNumber(value));
      return;

    case "string":
      out.push(escapeString(value));
      return;

    case "object":
      if (Array.isArray(value)) {
        writeArray(out, value);
      } else {
        writeObject(out, value as Record<string, JsonValue | undefined>);
      }
      return;

    default:
      throw new Error(
        `jcs: value of type ${typeof value} is not JSON-serializable`,
      );
  }
}

function writeArray(out: string[], values: JsonValue[]): void {
  out.push("[");
  values.forEach((element, index) => {
    if (index > 0) out.push(",");
    if (element === undefined) {
      throw new Error(`jcs: array element ${index} is undefined`);
    }
    writeValue(out, element);
  });
  out.push("]");
}

function writeObject(
  out: string[],
  object: Record<string, JsonValue | undefined>,
): void {
  const keys = Object.keys(object)
    .filter((key) => object[key] !== undefined)
    .sort(compareCodePoints);

  out.push("{");
  keys.forEach((key, index) => {
    if (index > 0) out.push(",");
    out.push(escapeString(key));
    out.push(":");
    writeValue(out, object[key]);
  });
  out.push("}");
}

/**
 * Order two strings by Unicode code point, the ordering Go's `sort.Strings`
 * produces over UTF-8 and the one the reference canonicalizer therefore
 * uses. JavaScript's own relational operators compare UTF-16 code units,
 * which places astral characters (encoded as surrogates in the 0xD800 range)
 * below U+E000..U+FFFF rather than above.
 */
export function compareCodePoints(a: string, b: string): number {
  const left = Array.from(a);
  const right = Array.from(b);
  const shared = Math.min(left.length, right.length);

  for (let i = 0; i < shared; i++) {
    const x = (left[i] as string).codePointAt(0) as number;
    const y = (right[i] as string).codePointAt(0) as number;
    if (x !== y) return x < y ? -1 : 1;
  }

  return left.length - right.length;
}

/**
 * Format a number per ECMAScript's `Number::toString`, which is what both
 * RFC 8785 and the reference implementation converge on.
 *
 * Integers within the safe-integer range are written as plain decimals. The
 * reference implementation reaches the same result by a different route (it
 * prints integral floats with `%d`), and the two agree across the whole
 * range the protocol uses, where every monetary amount is a decimal string
 * rather than a JSON number.
 */
function formatNumber(value: number): string {
  if (!Number.isFinite(value)) {
    throw new Error(`jcs: ${value} is not a finite number`);
  }

  // String() renders -0 as "0" and never reaches exponent notation inside
  // the safe-integer range, matching the reference implementation's %d.
  if (Number.isInteger(value) && Math.abs(value) <= Number.MAX_SAFE_INTEGER) {
    return String(value);
  }

  return JSON.stringify(value) as string;
}

/**
 * Escape characters that must not appear literally inside a JSON string,
 * reproducing Go's `encoding/json` escaping: the two mandatory escapes, the
 * short forms for the five control characters that have one, `\u00xx` for
 * the remaining C0 controls, and the HTML-safety escapes for "<", ">", "&",
 * U+2028, and U+2029.
 *
 * There are five short forms, `\b`, `\f`, `\n`, `\r`, and `\t`, and the
 * reference implementation emits all five, as does RFC 8785. Spelling the
 * first two out as six-character `\u00xx` escapes parses back to the same
 * string but is a different sequence of bytes, and the bytes are what the
 * challenge id's HMAC is computed over.
 */
function escapeString(value: string): string {
  let out = '"';

  for (const char of value) {
    const code = char.codePointAt(0) as number;

    switch (char) {
      case '"':
        out += '\\"';
        continue;
      case "\\":
        out += "\\\\";
        continue;
      case "\b":
        out += "\\b";
        continue;
      case "\f":
        out += "\\f";
        continue;
      case "\n":
        out += "\\n";
        continue;
      case "\r":
        out += "\\r";
        continue;
      case "\t":
        out += "\\t";
        continue;
      case "<":
        out += "\\u003c";
        continue;
      case ">":
        out += "\\u003e";
        continue;
      case "&":
        out += "\\u0026";
        continue;
      default:
        break;
    }

    // The two line separators are matched by code point rather than by a
    // literal in the switch above, so that this source file stays free of
    // characters that some tooling treats as line breaks.
    if (code === 0x2028 || code === 0x2029) {
      out += `\\u${code.toString(16)}`;
      continue;
    }

    if (code < 0x20) {
      out += `\\u${code.toString(16).padStart(4, "0")}`;
      continue;
    }

    // A lone surrogate is not a character, and the two implementations
    // disagree on what to do with one: Go substitutes U+FFFD while
    // JavaScript emits an escape for the surrogate itself. Refuse rather
    // than silently sign different bytes than the peer would.
    if (code >= 0xd800 && code <= 0xdfff) {
      throw new Error(
        `jcs: string contains an unpaired surrogate U+${code
          .toString(16)
          .toUpperCase()}`,
      );
    }

    out += char;
  }

  return `${out}"`;
}

function describeError(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}
